@push('styles')<style>
.doc-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:25px}.doc-head h1{margin:5px 0;font-size:32px}.doc-head p,.doc-breadcrumb,.muted{margin:0;color:#64748b}.doc-breadcrumb{font-size:12px}.doc-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:22px}.doc-stat,.doc-card,.doc-form{background:#fff;border:1px solid #e2e8f0;border-radius:13px;box-shadow:0 1px 3px #0f172a12}.doc-stat{padding:19px}.doc-stat strong{display:block;font-size:29px}.doc-stat span{color:#64748b;font-size:12px}.doc-card,.doc-form{overflow:hidden}.doc-card+.doc-card{margin-top:20px}.doc-card-head{display:flex;justify-content:space-between;align-items:center;padding:17px 20px;border-bottom:1px solid #e2e8f0}.doc-card-head h2{margin:0;font-size:18px}.doc-table-wrap{overflow-x:auto}.doc-table{width:100%;border-collapse:collapse}.doc-table th,.doc-table td{padding:14px 18px;text-align:left;border-bottom:1px solid #e2e8f0}.doc-table th{font-size:11px;text-transform:uppercase;color:#64748b;background:#f8fafc}.doc-status{display:inline-flex;padding:5px 9px;border-radius:99px;font-size:12px;font-weight:700}.doc-status.valid{background:#dcfce7;color:#166534}.doc-status.to_renew{background:var(--warning-pale);color:#824519;border:1px solid var(--warning)}.doc-status.expired{background:#fee2e2;color:#991b1b}.review-status{display:inline-flex;padding:5px 8px;border-radius:99px;font-size:10px;font-weight:800}.review-status.pending{background:#FFF7E5;color:#805d16}.review-status.approved{background:#E8F5F0;color:#076047}.review-status.rejected{background:#fff0f0;color:#a32130}.review-reason{display:block;max-width:320px;margin-top:5px;color:#a32130;font-size:11px;line-height:1.4}.required-type{display:block;width:max-content;margin-top:5px;padding:3px 6px;border-radius:99px;background:#e8f5f0;color:#076047;font-size:9px;font-weight:900;text-transform:uppercase}.doc-link{color:var(--green);font-weight:700;text-decoration:none}.doc-form-body{padding:24px}.doc-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.doc-field.full{grid-column:1/-1}.doc-field label{display:block;margin-bottom:7px;font-size:13px;font-weight:700}.doc-field input,.doc-field select{width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:8px;background:#fff}.upload-zone{padding:22px!important;border:2px dashed #b8ddcf!important;background:var(--bg)!important}.doc-help{display:block;margin-top:6px;color:#64748b;font-size:12px}.doc-error{display:block;margin-top:5px;color:#b91c1c;font-size:12px}.doc-errors{margin:0 24px 20px;padding:14px;border-radius:9px;background:#fef2f2;color:#991b1b}.doc-note{padding:13px;border-radius:8px;background:#E8F5F0;color:var(--dark);font-size:12px}.doc-form-footer{display:flex;justify-content:flex-end;gap:10px;padding:18px 24px;border-top:1px solid #e2e8f0;background:#f8fafc}.required{color:var(--danger)}
@media(max-width:800px){.doc-summary{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.doc-head{align-items:flex-start;flex-direction:column}.doc-summary,.doc-grid{grid-template-columns:1fr}.doc-field.full{grid-column:auto}.doc-form-footer{flex-direction:column-reverse}}
</style>@endpush
